"use strict";(self.webpackChunksalat_e_mustaqeem_client=self.webpackChunksalat_e_mustaqeem_client||[]).push([[8627],{78627:e=>{e.exports=JSON.parse('{"meta":{"title":"AI Agents - iMuslim Life","description":"Ask Claude, ChatGPT, Gemini or Copilot for today\'s prayer times, Qibla and Hijri date. Connect our free MCP server in a minute, no API key needed."},"chip":"New: MCP server","h1":"Prayer times for your AI assistant","lede":"Connect Claude, ChatGPT, Gemini or Copilot to the Muslim Companion prayer-times server. Your assistant then answers with real calculated times for your city and method, not a guess.","copy":"Copy","copied":"Copied","toolsH2":"What your assistant can do","toolsSub":"Six read-only tools. Times are calculated for the place\u2019s own timezone, with your choice of calculation method and Asr madhab.","tools":{"prayer":{"title":"Prayer times for any day","text":"Fajr, Sunrise, Dhuhr, Asr, Maghrib and Isha for a place and date, in local time, with the Hijri date."},"next":{"title":"Next prayer","text":"Which prayer is next, its time and how many minutes until it."},"find":{"title":"Find a place","text":"Turns a city or address into coordinates and a timezone."},"hijri":{"title":"Hijri date","text":"The Islamic date for any Gregorian date."},"qibla":{"title":"Qibla direction","text":"Direction of the Kaaba from any place, in degrees and as a compass point."},"methods":{"title":"Calculation methods","text":"ISNA, Muslim World League, Umm al-Qura, Karachi and 11 more, plus Hanafi or standard Asr."}},"setupH2":"Set it up","tabDevelopers":"Developers","claude":{"s1":"On <b>claude.ai</b> or in <b>Claude Desktop</b>, open <b>Settings \u2192 Connectors</b>.","s2":"Choose <b>Add custom connector</b>. Name it <b>Muslim Companion</b> and paste the server URL below.","s3":"Save. In a chat, turn the connector on (from the tools menu) and ask: <i>\u201cWhen is Maghrib in Toronto today?\u201d</i>","note":"Custom connectors depend on your Claude plan. For Claude Code, run the command below instead."},"chatgpt":{"s1":"In ChatGPT, open <b>Settings \u2192 Apps & Connectors</b>, then <b>Advanced settings</b>, and turn on <b>Developer mode</b>.","s2":"Choose <b>Create</b> (new connector). Name it <b>Muslim Companion</b>, paste the server URL below, and choose <b>No authentication</b>.","s3":"In a new chat, add the connector and ask: <i>\u201cWhat are today\u2019s prayer times in London, Hanafi Asr?\u201d</i>","note":"Developer mode connectors depend on your ChatGPT plan, and menu names can change between versions."},"gemini":{"s1":"Open <b>~/.gemini/settings.json</b> (create it if it doesn\u2019t exist).","s2":"Add the <b>muslim-companion</b> entry below under <b>mcpServers</b>, then restart Gemini CLI.","s3":"Run <b>/mcp</b> to check it\u2019s connected, then ask about prayer times."},"vscode":{"s1":"In your project, create <b>.vscode/mcp.json</b> (or run <b>MCP: Add Server</b> from the Command Palette and choose <b>HTTP</b>).","s2":"Paste the configuration below and click <b>Start</b> above the server entry.","s3":"In Copilot Chat, switch to <b>Agent</b> mode and ask about prayer times."},"dev":{"s1":"Any MCP client can connect: the server speaks <b>Streamable HTTP</b>, is stateless, and needs no API key.","s2":"Call a tool with a JSON-RPC <b>POST</b>, as in the example below.","s3":"Read <a>llms.txt</a> for a short overview written for language models.","note":"Limits: 60 requests per minute and 600 per hour per client. Please cache a day\u2019s times instead of asking repeatedly."},"tryAsk":"Try asking: <i>\u201cWhen is Fajr tomorrow in Orlando?\u201d</i> \xb7 <i>\u201cWhich way is the qibla from Karachi?\u201d</i> \xb7 <i>\u201cWhat is today\u2019s Hijri date?\u201d</i> \xb7 <i>\u201cHow long until Asr in Toronto, Hanafi?\u201d</i>","privacyH":"Public data only","privacy":"The server only provides public information: prayer times, Hijri dates, qibla directions and calculation methods. It needs no account and cannot see or change anything in your Muslim Companion settings. Features that act for you, such as reading your own Athan schedule, will come later and will always require you to sign in and approve access. See our <a>Privacy Policy</a>.","alexaCta":"Muslim Companion for Alexa"}')}}]);